import{_ as s,C as i,o as t,c as r,j as e,a as d,E as n,a5 as c}from"./chunks/framework.B1qnvv14.js";const v=JSON.parse('{"title":"Solução de problemas","description":"","frontmatter":{"title":"Solução de problemas"},"headers":[],"relativePath":"solucao-de-problemas.md","filePath":"solucao-de-problemas.md","lastUpdated":1792102410000}'),l={name:"solucao-de-problemas.md"};function p(h,a,u,m,k,g){const o=i("CopyOrDownloadAsMarkdownButtons");return t(),r("div",null,[a[0]||(a[0]=e("h1",{id:"solucao-de-problemas",tabindex:"-1"},[d("Solução de problemas "),e("a",{class:"header-anchor",href:"#solucao-de-problemas","aria-label":'Permalink to "Solução de problemas"'},"​")],-1)),n(o),a[1]||(a[1]=c('<p>Comece sempre por <code>automacli profile</code> dentro da task: ele mostra qual arquivo de perfil está valendo e a porta de cada serviço.</p><h2 id="port-is-already-allocated-ao-subir-a-stack" tabindex="-1">&quot;port is already allocated&quot; ao subir a stack <a class="header-anchor" href="#port-is-already-allocated-ao-subir-a-stack" aria-label="Permalink to &quot;&quot;port is already allocated&quot; ao subir a stack&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Causa provável</th><th>Como conferir</th><th>Correção</th></tr></thead><tbody><tr><td>O override não está sendo carregado</td><td><code>docker compose config</code> não mostra as portas do slot</td><td>Com <code>-f</code> explícito, o Compose ignora o override: liste o Makefile/script em <code>compose.wireInto</code> ou acrescente <code>-f docker-compose.override.yml</code>.</td></tr><tr><td>A stack compartilhada está parada</td><td><code>automacli shared status</code> mostra <code>parado</code></td><td><code>automacli shared up</code>.</td></tr><tr><td>O serviço deveria ser compartilhado e não está no perfil</td><td><code>automacli profile</code> não o marca como compartilhado</td><td>Adicione-o a <code>shared.services</code>.</td></tr><tr><td>Duas portas colidem depois do deslocamento</td><td>Tabela de <code>automacli profile</code> com portas repetidas</td><td>Aumente <code>slots.offset</code>.</td></tr><tr><td><code>port is already allocated</code> ao subir a stack temporária de um script no repo base</td><td>Outro slot publica uma porta igual à do slot 0 (ex.: <code>adm-api</code> do slot 8 na <code>8808</code>)</td><td>Pare a stack daquele slot enquanto o script roda. Tasks criadas com a versão atual já não recebem slots que colidem.</td></tr></tbody></table><h2 id="all-predefined-address-pools-have-been-fully-subnetted" tabindex="-1">&quot;all predefined address pools have been fully subnetted&quot; <a class="header-anchor" href="#all-predefined-address-pools-have-been-fully-subnetted" aria-label="Permalink to &quot;&quot;all predefined address pools have been fully subnetted&quot;&quot;">​</a></h2><p>O Docker reserva uma sub-rede para cada projeto compose e, por padrão, só tem 31. Cada slot usa uma, e comandos rodados sem <code>-p</code> fora da raiz da task (ou com <code>compose.projectNameEnv: false</code>) criam mais uma com o nome do diretório, que fica para trás depois do <code>run --rm</code>.</p><p>Para liberar na hora, remova as redes que nenhum container usa:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span></span></code></pre></div><p>Para não voltar a acontecer, aumente os pools em <code>/etc/docker/daemon.json</code> e reinicie o Docker:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;default-address-pools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;base&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;172.16.0.0/12&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">24</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Isso dá 4096 redes de 254 endereços e tira o Docker da faixa <code>192.168.x</code>, que costuma colidir com a rede local. O <code>scripts/install-system-limits.sh</code> já grava essa chave quando o <code>daemon.json</code> ainda não define <code>default-address-pools</code>; se já definir, ajuste à mão. Redes existentes mantêm a sub-rede antiga até serem recriadas.</p><h2 id="automacli-profile-nao-mostra-nenhuma-porta" tabindex="-1"><code>automacli profile</code> não mostra nenhuma porta <a class="header-anchor" href="#automacli-profile-nao-mostra-nenhuma-porta" aria-label="Permalink to &quot;`automacli profile` não mostra nenhuma porta&quot;">​</a></h2><ul><li><code>compose.files</code> aponta para arquivos que não existem nesse diretório.</li><li>As portas não têm host fixo (<code>&quot;3000&quot;</code> sozinho) ou são faixas; declare-as em <code>ports.services</code>.</li><li>A porta de host vem de uma variável sem valor (<code>${API_PORT}:3000</code>): sem <code>.env</code>, nem o <code>docker compose config</code> nem a leitura direta do YAML conseguem resolvê-la. Crie o <code>.env</code> ou declare essas portas em <code>ports.services</code>.</li></ul><h2 id="a-aplicacao-ainda-chama-a-porta-antiga" tabindex="-1">A aplicação ainda chama a porta antiga <a class="header-anchor" href="#a-aplicacao-ainda-chama-a-porta-antiga" aria-label="Permalink to &quot;A aplicação ainda chama a porta antiga&quot;">​</a></h2><p>O override só muda o Docker. A porta está escrita em algum arquivo que não entrou em <code>rewrite</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;:4000&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;.env*&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;package.json&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>Acrescente o arquivo a uma regra de <a href="./perfil#rewrite"><code>rewrite</code></a>. Se a porta é de um processo fora do compose, inclua-a em <code>ports.extra</code>. A reescrita acontece no <code>clone</code>; em uma task já criada, ajuste o arquivo à mão.</p><h2 id="a-task-subiu-com-o-banco-vazio" tabindex="-1">A task subiu com o banco vazio <a class="header-anchor" href="#a-task-subiu-com-o-banco-vazio" aria-label="Permalink to &quot;A task subiu com o banco vazio&quot;">​</a></h2><ul><li>O serviço de banco não está em <code>shared.services</code>, então cada task tem o seu.</li><li>O volume não está em <code>shared.volumes</code>.</li><li><code>compose.projectName</code> difere do nome com que a sua stack principal roda. Os volumes compartilhados se chamam <code>&lt;projectName&gt;_&lt;volume&gt;</code>: confira com <code>docker volume ls</code>.</li></ul><h2 id="todas-as-tasks-perderam-o-banco-ou-o-dns-de-uma-vez" tabindex="-1">Todas as tasks perderam o banco ou o DNS de uma vez <a class="header-anchor" href="#todas-as-tasks-perderam-o-banco-ou-o-dns-de-uma-vez" aria-label="Permalink to &quot;Todas as tasks perderam o banco ou o DNS de uma vez&quot;">​</a></h2><p>Os compartilhados estavam rodando dentro de uma task que foi parada (perfis com <code>shared.host: first-task</code>, ou stacks criadas antes da stack compartilhada). Confira com <code>automacli shared status</code> e suba a partir do repo base com <code>automacli shared up</code>, que move o que ainda estiver em alguma task.</p><h2 id="o-monitor-mostra-a-task-sem-containers" tabindex="-1">O monitor mostra a task sem containers <a class="header-anchor" href="#o-monitor-mostra-a-task-sem-containers" aria-label="Permalink to &quot;O monitor mostra a task sem containers&quot;">​</a></h2><p>O projeto compose em execução não é o registrado no <code>.slot</code>. Isso acontece quando a stack foi iniciada com outro <code>-p</code> ou sem <code>COMPOSE_PROJECT_NAME</code>. Compare <code>cat .slot</code> com <code>docker compose ls</code>.</p><h2 id="cada-task-parece-ocupar-o-disco-inteiro-de-novo" tabindex="-1">Cada task parece ocupar o disco inteiro de novo <a class="header-anchor" href="#cada-task-parece-ocupar-o-disco-inteiro-de-novo" aria-label="Permalink to &quot;Cada task parece ocupar o disco inteiro de novo&quot;">​</a></h2><p><code>du</code> e gerenciadores de arquivos mostram o tamanho aparente, que conta de novo os blocos compartilhados pelo reflink. Para ver o que cada task ocupa de fato:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">btrfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filesystem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> du</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/tasks/task-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span></span></code></pre></div><p>A coluna <code>Exclusive</code> é o que você recupera apagando a task. O <a href="./monitor#disco-aparente-e-real">monitor</a> mostra os dois números. O que faz uma task crescer é o que ela gera depois do clone: dependências reinstaladas e builds deixam de ser compartilhados.</p><h2 id="o-clone-nao-usou-reflink" tabindex="-1">O clone não usou reflink <a class="header-anchor" href="#o-clone-nao-usou-reflink" aria-label="Permalink to &quot;O clone não usou reflink&quot;">​</a></h2><p><code>cp --reflink</code> só funciona em Btrfs, XFS (com reflink habilitado) e APFS, com origem e destino no mesmo sistema de arquivos; em Btrfs o automacli prefere um snapshot do repo base. Sem reflink ele cai para <code>git clone --reference</code>, que reaproveita os objetos do repo base mas não traz as dependências instaladas. <code>automacli doctor</code> mostra a estratégia escolhida e por que as outras foram descartadas.</p><h2 id="um-servico-parou-de-responder-sem-erro-aparente" tabindex="-1">Um serviço parou de responder sem erro aparente <a class="header-anchor" href="#um-servico-parou-de-responder-sem-erro-aparente" aria-label="Permalink to &quot;Um serviço parou de responder sem erro aparente&quot;">​</a></h2><p>Sintomas típicos: <code>502</code> no load balancer, container que reinicia sozinho, teste que termina com <code>Killed</code> ou código 137. Verifique se ele foi morto por falta de memória:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> oom</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1h</span></span></code></pre></div><p>Se aparecer na lista, veja <a href="./isolamento#saber-o-que-foi-morto">como ler o motivo</a>.</p><h2 id="containers-presos-em-restarting" tabindex="-1">Containers presos em &quot;Restarting&quot; <a class="header-anchor" href="#containers-presos-em-restarting" aria-label="Permalink to &quot;Containers presos em &quot;Restarting&quot;&quot;">​</a></h2><p>Workers que dependem de um serviço compartilhado reiniciam em laço quando ele cai. Pare-os e suba a stack que hospeda os serviços compartilhados primeiro:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status=restarting</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xargs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><h2 id="perfil-invalido" tabindex="-1">Perfil inválido <a class="header-anchor" href="#perfil-invalido" aria-label="Permalink to &quot;Perfil inválido&quot;">​</a></h2><p>A mensagem aponta o campo. Erros comuns: indentação do YAML, <code>mode</code> de <code>rewrite</code> diferente de <code>env</code>, <code>cli-flags</code> ou <code>urls</code>, e portas fora do formato <code>host:container</code>.</p><h2 id="owner-ou-repositorio-identificados-errado" tabindex="-1">Owner ou repositório identificados errado <a class="header-anchor" href="#owner-ou-repositorio-identificados-errado" aria-label="Permalink to &quot;Owner ou repositório identificados errado&quot;">​</a></h2><p>O automacli lê <code>owner</code> e <code>repo</code> do <code>.slot</code> da task; sem <code>.slot</code>, do remoto <code>origin</code>; sem remoto, deduz do nome <code>task-&lt;branch&gt;-&lt;owner&gt;-&lt;repo&gt;</code>, o que falha quando owner ou repo têm hífen. Confira com <code>cat .slot</code> e <code>git remote get-url origin</code>.</p>',39))])}const f=s(l,[["render",p]]);export{v as __pageData,f as default};
